/// F2 · Tab "Hôm nay" — danh sách KH cần thăm hôm nay theo tuyến (R-APP-2.1).
class RouteScreen extends StatefulWidget {
  const RouteScreen({super.key, PilotRouteService? service, AppDatabase? db})
      : _service = service,
        _db = db;

  final PilotRouteService? _service;
  final AppDatabase? _db;

  @override
  State<RouteScreen> createState() => _RouteScreenState();
}

/// Trạng thái viếng thăm của 1 KH trong ngày (QĐ (d): hoàn tất = ĐÃ CHECK-OUT).
enum _VisitCardState { notVisited, inProgress, done }

class _RouteScreenState extends State<RouteScreen> {
  late final AppDatabase _db = widget._db ?? DmsServices.instance.db;
  late final PilotRouteService _service =
      widget._service ?? PilotRouteService(_db);

  final String _date = DateTime.now().toIso8601String().substring(0, 10);
  final _searchController = TextEditingController();

  PilotRoute? _route;
  bool _loading = true;
  String _query = '';

  /// Phiên viếng thăm local HÔM NAY đang mở: customer → client_uuid.
  Map<int, String> _openVisits = const {};

  /// KH đã CHECK-OUT hôm nay theo phiên local.
  Set<int> _closedVisits = const {};

  /// KH đóng lượt với outcome "điểm bán đóng cửa" (64B Việc A) — nhãn riêng.
  Set<int> _storeClosedVisits = const {};

  /// Phiên local ĐÃ ĐÓNG hôm nay: customer → client_uuid (đối chiếu outbox).
  Map<int, String> _closedVisitUuids = const {};

  /// client_uuid phiên có `visit.close` CHƯA lên máy chủ (còn chờ / lỗi) →
  /// nút "Đã viếng thăm*" + icon đám mây: máy đã check-out, server chưa nhận.
  Set<String> _unsyncedCloseUuids = const {};
  StreamSubscription<List<OutboxData>>? _closeOutboxSub;

  /// BUG 1 (doc 39): WATCH bảng visits local — check-in/check-out ghi ở máy
  /// (offline-first) phải đổi thẻ NGAY, kể cả khi luồng viếng thăm được mở
  /// từ banner/màn khác (không đi qua [_openVisit] nên không có chỗ reload).
  StreamSubscription<List<Visit>>? _visitsSub;

  /// APP-4 (coords): KH trong tuyến CHƯA có toạ độ (mirror `customers` local
  /// lat/lng null) → badge nhắc sale cập nhật khi ghé điểm bán.
  Set<int> _missingCoords = const {};

  @override
  void initState() {
    super.initState();
    _watchTodayVisits();
    _watchUnsyncedCloses();
    _load();
  }

  @override
  void dispose() {
    _visitsSub?.cancel();
    _closeOutboxSub?.cancel();
    _searchController.dispose();
    super.dispose();
  }

  /// Nguồn trạng thái ƯU TIÊN LOCAL: stream DB đẩy thay đổi phiên viếng thăm
  /// (mở/đóng) vào UI NGAY — không chờ sync, không bắt sale kéo refresh.
  ///
  /// 64C: lượt ĐANG MỞ lấy theo MỌI ngày (không chỉ hôm nay) — lượt treo từ
  /// hôm trước (adopt về sau khi cài lại máy) phải hiện "đang viếng thăm" để
  /// sale resume/check-out được và guard chặn mở điểm mới hoạt động đúng.
  /// Lượt ĐÃ ĐÓNG vẫn chỉ tính hôm nay (badge "đã thăm" theo ngày).
  void _watchTodayVisits() {
    final now = DateTime.now();
    final startOfDayUtc = DateTime(now.year, now.month, now.day).toUtc();
    _visitsSub = (_db.select(_db.visits)
          ..where((t) =>
              t.status.equals(1) |
              t.openedAt.isBiggerOrEqualValue(startOfDayUtc)))
        .watch()
        .listen((rows) {
      final open = <int, String>{};
      final closed = <int>{};
      final closedUuids = <int, String>{};
      final storeClosed = <int>{};
      for (final v in rows) {
        if (v.status == 2) {
          closed.add(v.customer);
          closedUuids[v.customer] = v.clientUuid;
          if (v.outcome == VisitService.outcomeStoreClosed) {
            storeClosed.add(v.customer);
          }
        } else if (v.status == 1) {
          open[v.customer] = v.clientUuid;
        }
      }
      if (mounted) {
        setState(() {
          _openVisits = open;
          _closedVisits = closed;
          _closedVisitUuids = closedUuids;
          _storeClosedVisits = storeClosed;
        });
      }
    });
  }

  static final _visitRefPattern =
      RegExp('"${OutboxDispatcher.refPrefix}([^"]+)"');

  /// Theo dõi `visit.close` chưa gửi xong (pending/failed) trong outbox.
  void _watchUnsyncedCloses() {
    _closeOutboxSub = (_db.select(_db.outbox)
          ..where((t) =>
              t.type.equals('visit.close') &
              t.status.isIn([OutboxStatus.pending, OutboxStatus.failed])))
        .watch()
        .listen((rows) {
      final uuids = <String>{
        for (final r in rows)
          for (final m in _visitRefPattern.allMatches(r.payloadJson))
            m.group(1)!,
      };
      if (mounted) setState(() => _unsyncedCloseUuids = uuids);
    });
  }

  bool _closeUnsynced(PilotRouteCustomer c) {
    final uuid = _closedVisitUuids[c.id];
    return uuid != null && _unsyncedCloseUuids.contains(uuid);
  }

  /// APP-1: khớp tên / mã KH / SĐT, không phân biệt hoa thường + BỎ DẤU
  /// (gõ `hien thoi` phải ra `Hiền Thời`). Lọc client-side trên list đã nạp.
  bool _matchesQuery(PilotRouteCustomer c, String normalizedQuery) {
    if (normalizedQuery.isEmpty) return true;
    return normalizeVn(c.name).contains(normalizedQuery) ||
        normalizeVn(c.code ?? '').contains(normalizedQuery) ||
        normalizeVn(c.contactNumber ?? '').contains(normalizedQuery);
  }

  Widget _searchField() {
    return Container(
      height: 44,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.grey.shade300),
      ),
      child: TextField(
        controller: _searchController,
        onChanged: (v) => setState(() => _query = v),
        decoration: InputDecoration(
          hintText: 'Tìm KH theo tên, mã, SĐT...',
          hintStyle: TextStyle(color: Colors.grey.shade500, fontSize: 14),
          prefixIcon: const Icon(Icons.search, color: Colors.grey, size: 22),
          suffixIcon: _query.isNotEmpty
              ? IconButton(
                  icon: const Icon(Icons.clear, size: 20),
                  onPressed: () {
                    _searchController.clear();
                    setState(() => _query = '');
                  },
                )
              : null,
          border: InputBorder.none,
          contentPadding: const EdgeInsets.symmetric(vertical: 12),
        ),
      ),
    );
  }

  Future<void> _load() async {
    setState(() => _loading = true);
    final route = await _service.getToday(_date);
    // Phiên viếng thăm local do STREAM [_watchTodayVisits] lo (BUG 1 doc 39)
    // — thẻ đổi ngay khi máy ghi, không phụ thuộc lần reload này.
    var missingCoords = <int>{};
    try {
      missingCoords = await _loadMissingCoords(route);
    } on Object {
      // DB local lỗi bất thường → vẫn hiện tuyến.
    }
    if (mounted) {
      setState(() {
        _route = route;
        _missingCoords = missingCoords;
        _loading = false;
      });
    }
  }

  /// KH trong tuyến có bản ghi mirror local nhưng lat/lng null = xác nhận
  /// chưa có toạ độ. KH chưa sync về máy → không rõ → KHÔNG gắn badge (tránh
  /// nhiễu). `today_route` hiện không mang lat/lng nên đọc từ DB local.
  Future<Set<int>> _loadMissingCoords(PilotRoute route) async {
    final ids = route.customers.map((c) => c.id).toList(growable: false);
    if (ids.isEmpty) return const {};
    final rows = await (_db.select(_db.customers)
          ..where((t) => t.id.isIn(ids)))
        .get();
    return {
      for (final r in rows)
        if (r.lat == null || r.lng == null) r.id,
    };
  }

  /// QĐ (d): "hoàn tất viếng thăm" tính khi CHECK-OUT xong.
  ///
  /// BUG 1 (doc 39) — thứ tự ƯU TIÊN DỮ LIỆU LOCAL (App offline-first, thao
  /// tác vừa xảy ra trên máy phải phản ánh ngay từ dữ liệu máy):
  /// 1. Local có phiên ĐÃ ĐÓNG hôm nay → done
  /// 2. Local có phiên đang mở → inProgress
  /// 3. Cờ server checkout_today → done (phiên thiết bị khác / đã sync)
  /// 4. Cờ server checkin_today → inProgress
  _VisitCardState _visitStateOf(PilotRouteCustomer c) {
    if (_closedVisits.contains(c.id)) return _VisitCardState.done;
    if (_openVisits.containsKey(c.id)) return _VisitCardState.inProgress;
    if (c.checkoutToday) return _VisitCardState.done;
    if (c.checkinToday) return _VisitCardState.inProgress;
    return _VisitCardState.notVisited;
  }

  String _weekdayLabel(int d) {
    const names = {1: 'Thứ 2', 2: 'Thứ 3', 3: 'Thứ 4', 4: 'Thứ 5', 5: 'Thứ 6', 6: 'Thứ 7', 7: 'Chủ nhật'};
    // BE day_of_week có thể theo 2=T2..8=CN; chuẩn hoá về DateTime weekday.
    final wd = DateTime.parse(_date).weekday;
    return names[wd] ?? 'Hôm nay';
  }

  Customer _toCustomer(PilotRouteCustomer c) => Customer(
        id: c.id,
        name: c.name,
        code: c.code ?? '',
        contactNumber: c.contactNumber,
        addressRaw: c.addressRaw,
        displayLabel: c.name,
      );

  /// QD-16: check-in tại điểm bán là LỐI VÀO DUY NHẤT qua visit_flow.
  ///
  /// Doc 37 (đổi ý so với 33): bấm "Viếng thăm" → mở NGAY danh sách 5 bước;
  /// chưa check-in thì bước 2–5 khoá (check-in là bước 1). Phiên đang mở →
  /// tiếp tục, KHÔNG bắt check-in lại.
  Future<void> _openVisit(PilotRouteCustomer c) async {
    // Việc B (64B) — chặn CHỦ ĐỘNG: còn lượt mở dở ở KH KHÁC → không mở
    // điểm mới, chỉ đường về điểm đang mở để check-out/đóng cửa. Bấm lại
    // chính KH đang dở → resume bình thường (không chặn nhầm retry).
    MapEntry<int, String>? blockedBy;
    for (final e in _openVisits.entries) {
      if (e.key != c.id) {
        blockedBy = e;
        break;
      }
    }
    if (blockedBy != null) {
      final openId = blockedBy.key;
      final openUuid = blockedBy.value;
      String name = 'KH #$openId';
      for (final rc in _route?.customers ?? const <PilotRouteCustomer>[]) {
        if (rc.id == openId) {
          name = rc.name;
          break;
        }
      }
      await showOpenVisitBlockDialog(
        context,
        openCustomerName: name,
        onGoToOpenVisit: () => _resumeOpenVisit(openId, name, openUuid),
      );
      return;
    }
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => VisitFlowScreen(
          customer: c.id,
          customerName: c.name,
          resumeVisitUuid: _openVisits[c.id],
        ),
      ),
    );
    await _load();
  }

  Future<void> _resumeOpenVisit(int customer, String name, String uuid) async {
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => VisitFlowScreen(
          customer: customer,
          customerName: name,
          resumeVisitUuid: uuid,
        ),
      ),
    );
    await _load();
  }

  Future<void> _openCreateOrder(PilotRouteCustomer c) async {
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => CreateOrderScreen(customer: _toCustomer(c)),
      ),
    );
    await _load();
  }

  /// APP-4: lịch sử 10 đơn + 5 viếng thăm gần nhất (rt.mobile/customer_360).
  Future<void> _openHistory(PilotRouteCustomer c) async {
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => Customer360Screen(
          customerId: c.id,
          customerName: c.name,
        ),
      ),
    );
  }

  Future<void> _openMap() async {
    // R-APP-2.3: bản đồ tuyến Goong. today_route (contract) CHƯA có lat/lng →
    // tra toạ độ từ DB customers (đã sync). TODO(BE): bổ sung lat/lng vào
    // bt.saleman/today_route để bản đồ đủ điểm.
    final custRows = await _db.select(_db.customers).get();
    final byId = {for (final c in custRows) c.id: c};
    final points = (_route?.customers ?? []).map((c) {
      final loc = byId[c.id];
      return TodayRoutePoint(
        routeLine: 0,
        customer: c.id,
        sequence: c.sequence,
        name: c.name,
        addressText: c.addressRaw,
        lat: loc?.lat,
        lng: loc?.lng,
        visited: _visitStateOf(c) == _VisitCardState.done,
      );
    }).toList();
    if (mounted) {
      Navigator.of(context).push(
        MaterialPageRoute(builder: (_) => RouteMapScreen(points: points)),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.grey.shade50,
      appBar: AppBar(
        title: const Text('Hôm nay'),
        actions: [
          IconButton(
            tooltip: 'Bản đồ tuyến',
            icon: const Icon(Icons.map_outlined),
            onPressed: (_route?.customers.isNotEmpty ?? false) ? _openMap : null,
          ),
          IconButton(
            tooltip: 'Làm mới',
            icon: const Icon(Icons.refresh),
            onPressed: _loading ? null : _load,
          ),
        ],
      ),
      body: _loading
          ? const Center(child: CircularProgressIndicator())
          : RefreshIndicator(onRefresh: _load, child: _body()),
    );
  }

  Widget _body() {
    final r = _route!;
    if (r.customers.isEmpty) {
      return ListView(
        children: [
          const SizedBox(height: 120),
          Icon(Icons.event_busy, size: 64, color: Colors.grey.shade400),
          const SizedBox(height: 12),
          Center(
            child: Text(
              // Doc 51: nói đúng nguồn lỗi — server lỗi ≠ ngoại tuyến.
              r.serverError != null
                  ? 'Không tải được tuyến từ máy chủ: ${r.serverError}'
                  : r.fromCache
                      ? 'Chưa có lịch tuyến — không kết nối được máy chủ'
                          ' và máy chưa có dữ liệu tải lần trước'
                      : 'Hôm nay không có KH trong tuyến',
              textAlign: TextAlign.center,
            ),
          ),
        ],
      );
    }

    // Giữ header tuyến + thanh tiến độ kể cả khi đang lọc (APP-1).
    final q = normalizeVn(_query);
    final filtered =
        r.customers.where((c) => _matchesQuery(c, q)).toList(growable: false);

    final children = <Widget>[
      _header(r),
      const SizedBox(height: 12),
      _searchField(),
      const SizedBox(height: 12),
    ];

    if (filtered.isEmpty) {
      children.add(Padding(
        padding: const EdgeInsets.only(top: 32),
        child: Center(
          child: Text(
            'Không có KH khớp "$_query"',
            style: TextStyle(color: Colors.grey.shade600),
          ),
        ),
      ));
    } else {
      // APP-2: chia 2 nhóm — chưa hoàn tất (trên) · đã check-out (dưới).
      // Trong mỗi nhóm sort theo sequence; badge GIỮ NGUYÊN số thứ tự gốc.
      final pending = <PilotRouteCustomer>[];
      final done = <PilotRouteCustomer>[];
      for (final c in filtered) {
        (_visitStateOf(c) == _VisitCardState.done ? done : pending).add(c);
      }
      int bySequence(PilotRouteCustomer a, PilotRouteCustomer b) =>
          a.sequence.compareTo(b.sequence);
      pending.sort(bySequence);
      done.sort(bySequence);

      for (final c in pending) {
        children
          ..add(_customerCard(c))
          ..add(const SizedBox(height: 8));
      }
      if (done.isNotEmpty) {
        children.add(_doneDivider(done.length));
        for (final c in done) {
          children
            ..add(_customerCard(c))
