  Widget _body() {
    final r = _route!;
    if (r.customers.isEmpty) {
      return ListView(
        children: [
          const SizedBox(height: 120),
          Icon(Icons.event_busy, size: 64, color: Colors.grey.shade400),
          const SizedBox(height: 12),
          Center(
            child: Text(
              // Doc 51: nói đúng nguồn lỗi — server lỗi ≠ ngoại tuyến.
              r.serverError != null
                  ? 'Không tải được tuyến từ máy chủ: ${r.serverError}'
                  : r.fromCache
                      ? 'Chưa có lịch tuyến — không kết nối được máy chủ'
                          ' và máy chưa có dữ liệu tải lần trước'
                      : 'Hôm nay không có KH trong tuyến',
              textAlign: TextAlign.center,
            ),
          ),
        ],
      );
    }

    // Giữ header tuyến + thanh tiến độ kể cả khi đang lọc (APP-1).
    final q = normalizeVn(_query);
    final filtered =
        r.customers.where((c) => _matchesQuery(c, q)).toList(growable: false);

    final children = <Widget>[
      _header(r),
      const SizedBox(height: 12),
      _searchField(),
      const SizedBox(height: 12),
    ];

    if (filtered.isEmpty) {
      children.add(Padding(
        padding: const EdgeInsets.only(top: 32),
        child: Center(
          child: Text(
            'Không có KH khớp "$_query"',
            style: TextStyle(color: Colors.grey.shade600),
          ),
        ),
      ));
    } else {
      // APP-2: chia 2 nhóm — chưa hoàn tất (trên) · đã check-out (dưới).
      // Trong mỗi nhóm sort theo sequence; badge GIỮ NGUYÊN số thứ tự gốc.
      final pending = <PilotRouteCustomer>[];
      final done = <PilotRouteCustomer>[];
      for (final c in filtered) {
        (_visitStateOf(c) == _VisitCardState.done ? done : pending).add(c);
      }
      int bySequence(PilotRouteCustomer a, PilotRouteCustomer b) =>
          a.sequence.compareTo(b.sequence);
      pending.sort(bySequence);
      done.sort(bySequence);

      for (final c in pending) {
        children
          ..add(_customerCard(c))
          ..add(const SizedBox(height: 8));
      }
      if (done.isNotEmpty) {
        children.add(_doneDivider(done.length));
        for (final c in done) {
          children
            ..add(_customerCard(c))
            ..add(const SizedBox(height: 8));
        }
      }
    }

    return ListView(
      padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
      children: children,
    );
  }

  /// Dải phân cách giữa nhóm chưa hoàn tất và nhóm đã check-out (APP-2).
  Widget _doneDivider(int count) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 8),
      child: Row(
        children: [
          Expanded(child: Divider(color: Colors.grey.shade300)),
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 10),
            child: Text(
              'Đã hoàn tất ($count)',
              style: TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w600,
                color: Colors.grey.shade600,
              ),
            ),
          ),
          Expanded(child: Divider(color: Colors.grey.shade300)),
        ],
      ),
    );
  }

  Widget _header(PilotRoute r) {
    // BUG 1 (doc 39): "Đã thăm x/N" đếm theo CÙNG NGUỒN với thẻ/nhóm
    // "Đã hoàn tất" (ưu tiên local) — tránh thẻ nói "Đã viếng thăm" mà bộ
    // đếm vẫn nói số cũ của server.
    final doneCount = r.customers
        .where((c) => _visitStateOf(c) == _VisitCardState.done)
        .length;
    final pct = r.total == 0 ? 0.0 : doneCount / r.total;
    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        gradient: const LinearGradient(
          colors: [Color(0xFF1976D2), Color(0xFF42A5F5)],
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: BorderRadius.circular(16),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            '${_weekdayLabel(r.dayOfWeek)} — ${r.routeName.isEmpty ? "Tuyến" : r.routeName} — ${r.total} KH',
            style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold, fontSize: 16),
          ),
          const SizedBox(height: 10),
          Text('Đã thăm $doneCount/${r.total}',
              style: const TextStyle(color: Colors.white70)),
          // APP-2 (35A): số ĐƠN đã lên + tổng giá trị — BE tính (1 KH có thể
          // nhiều đơn, không đếm cờ order_today). BE chưa trả → ẩn dòng.
          if (r.ordersToday != null) ...[
            const SizedBox(height: 2),
            Text(
              'Đã lên ${r.ordersToday} đơn'
              '${r.ordersValueToday != null ? ' · ${NumberFormat.decimalPattern('vi').format(r.ordersValueToday)} đ' : ''}',
              style: const TextStyle(color: Colors.white70, fontSize: 13),
            ),
          ],
          const SizedBox(height: 6),
          ClipRRect(
            borderRadius: BorderRadius.circular(8),
            child: LinearProgressIndicator(
              value: pct,
              minHeight: 8,
              backgroundColor: Colors.white24,
              valueColor: const AlwaysStoppedAnimation(Colors.white),
            ),
          ),
          // Doc 51: CHỈ nói "ngoại tuyến" khi mất mạng thật; server lỗi →
          // hiện lý do thật từ BE (không đổ lỗi cho mạng).
          if (r.serverError != null) ...[
            const SizedBox(height: 8),
            Row(children: [
              const Icon(Icons.error_outline, color: Colors.white70, size: 14),
              const SizedBox(width: 4),
              Expanded(
                child: Text(
                  'Không tải được từ máy chủ: ${r.serverError} — đang hiện số cũ',
                  style: const TextStyle(color: Colors.white70, fontSize: 12),
                ),
              ),
            ]),
          ] else if (r.fromCache) ...[
            const SizedBox(height: 8),
            Row(children: const [
              Icon(Icons.cloud_off, color: Colors.white70, size: 14),
              SizedBox(width: 4),
              Text('Dữ liệu ngoại tuyến', style: TextStyle(color: Colors.white70, fontSize: 12)),
            ]),
          ],
        ],
      ),
    );
  }

