  /// Nút "Viếng thăm" đổi màu + nhãn theo 3 trạng thái (QĐ (d): xong khi
  /// CHECK-OUT). Đang viếng → bấm tiếp tục phiên dở.
  ///
  /// Check-out đã ghi ở máy nhưng `visit.close` chưa lên máy chủ → thêm `*` +
  /// icon đám mây (offline-first: sale làm tiếp được, nhưng biết chưa xong
  /// hẳn — điểm mới sẽ chờ check-out này gửi xong mới check-in lên server).
  Widget _visitButton(PilotRouteCustomer c, _VisitCardState state) {
    final unsynced = _closeUnsynced(c);
    final mark = unsynced ? '*' : '';
    return switch (state) {
      _VisitCardState.notVisited => _pillButton(
          icon: Icons.login,
          label: 'Viếng thăm',
          foreground: Colors.blue.shade800,
          background: Colors.blue.shade50,
          onTap: () => _openVisit(c),
        ),
      _VisitCardState.inProgress => _pillButton(
          icon: Icons.timelapse,
          label: 'Đang viếng thăm',
          foreground: Colors.white,
          background: Colors.orange.shade700,
          onTap: () => _openVisit(c),
        ),
      // 64B Việc A: lượt đóng với outcome store_closed → nhãn phân biệt
      // (vẫn tính đã viếng thăm, không có đơn).
      _VisitCardState.done when _storeClosedVisits.contains(c.id) =>
        _pillButton(
          icon: unsynced ? Icons.cloud_upload_outlined : Icons.storefront_outlined,
          label: 'Đã thăm · đóng cửa$mark',
          foreground: Colors.white,
          background: Colors.blueGrey.shade600,
          onTap: () => _openVisit(c),
        ),
      _VisitCardState.done => _pillButton(
          icon: unsynced ? Icons.cloud_upload_outlined : Icons.check_circle,
          label: 'Đã viếng thăm$mark',
          foreground: Colors.white,
          background: Colors.green.shade600,
          onTap: () => _openVisit(c),
        ),
    };
  }

  /// Nút gọn icon + chữ ngắn, đủ tương phản (a11y) — dùng cho hàng 3 nút.
  Widget _pillButton({
    required IconData icon,
    required String label,
    required Color foreground,
    required Color background,
    required VoidCallback onTap,
  }) {
    return Material(
      color: background,
      borderRadius: BorderRadius.circular(10),
      child: InkWell(
        borderRadius: BorderRadius.circular(10),
        onTap: onTap,
        child: Padding(
